import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../../controllers/saved_rooms_controller.dart';import '../../../controllers/auth_controller.dart';import '../../../app/routes/app_routes.dart';import '../../../shared/widgets/room_card.dart';
class SavedRoomsScreen extends GetView<SavedRoomsController>{const SavedRoomsScreen({super.key});@override Widget build(BuildContext context){final auth=Get.find<AuthController>();return Scaffold(appBar:AppBar(title:const Text('Saved rooms'),actions:[IconButton(onPressed:controller.load,icon:const Icon(Icons.refresh))]),body:Obx(()=>!auth.isLoggedIn?Center(child:FilledButton(onPressed:()=>Get.toNamed(AppRoutes.login),child:const Text('Sign in to view saved rooms'))):controller.loading.value?const Center(child:CircularProgressIndicator()):controller.error.value.isNotEmpty?Center(child:Text(controller.error.value)):controller.rooms.isEmpty?const Center(child:Text('No saved rooms yet. Tap the heart on a room to save it.')):RefreshIndicator(onRefresh:controller.load,child:ListView.separated(padding:const EdgeInsets.all(16),itemCount:controller.rooms.length,separatorBuilder:(_,__)=>const SizedBox(height:14),itemBuilder:(c,i)=>RoomCard(room:controller.rooms[i])))));}}
